// Custom OpenNext entrypoint: forwards HTTP requests and runs scheduled search indexing.
 // @ts-expect-error Generated by opennextjs-cloudflare build.
import openNextWorker from "./.open-next/worker.js";
import { createClient } from "@supabase/supabase-js";

type Env = {
  NEXT_PUBLIC_SUPABASE_URL: string;
  SUPABASE_SERVICE_ROLE_KEY: string;
  BULKSMSBD_API_KEY?: string;
  BULKSMSBD_SENDER_ID?: string;
  AI: {
    run(model: string, input: { text: string[] }): Promise<{ data?: number[][] }>;
  };
};

type ScheduledController = {
  cron: string;
  scheduledTime: number;
};

type ExecutionContextLike = {
  waitUntil(promise: Promise<unknown>): void;
};

type SearchJob = {
  job_id: string;
  product_id: string;
  attempts: number;
};

type Product = {
  id: string;
  name: string;
  description: string | null;
  sku: string | null;
  is_active: boolean;
};

async function processSearchEmbeddingQueue(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY || !env.AI) {
    throw new Error("Search embedding cron is missing required bindings.");
  }

  const supabase = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  const { data: jobs, error: claimError } = await supabase.rpc(
    "neweix_claim_search_embedding_jobs",
    { p_limit: 10 },
  );
  if (claimError) throw new Error(`Queue claim failed: ${claimError.message}`);
  if (!Array.isArray(jobs) || jobs.length === 0) {
    console.log("[search-cron] queue empty");
    return;
  }

  const typedJobs = jobs as SearchJob[];
  const { data: products, error: productsError } = await supabase
    .from("products")
    .select("id,name,description,sku,is_active")
    .in("id", typedJobs.map((job) => job.product_id));

  if (productsError) {
    await Promise.all(typedJobs.map((job) =>
      supabase.rpc("neweix_fail_search_embedding_job", {
        p_job_id: job.job_id,
        p_error: productsError.message,
      }),
    ));
    throw new Error(`Product lookup failed: ${productsError.message}`);
  }

  const productById = new Map<string, Product>(
    ((products ?? []) as Product[]).map((product) => [product.id, product]),
  );
  const activeJobs = typedJobs.filter((job) => productById.get(job.product_id)?.is_active === true);

  for (const job of typedJobs) {
    if (!activeJobs.some((active) => active.job_id === job.job_id)) {
      const { error } = await supabase.rpc("neweix_complete_search_embedding_job", {
        p_job_id: job.job_id,
      });
      if (error) console.error("[search-cron] stale job cleanup failed", job.job_id, error.message);
    }
  }

  if (activeJobs.length === 0) {
    console.log("[search-cron] removed inactive product jobs", typedJobs.length);
    return;
  }

  const texts = activeJobs.map((job) => {
    const product = productById.get(job.product_id)!;
    return [
      product.name,
      product.sku ? `SKU ${product.sku}` : "",
      product.description ?? "",
    ].filter(Boolean).join(". ").slice(0, 2000);
  });

  let vectors: number[][] | undefined;
  try {
    const result = await env.AI.run("@cf/baai/bge-m3", { text: texts });
    vectors = result.data;
  } catch (error) {
    const message = error instanceof Error ? error.message : "Workers AI embedding failed";
    await Promise.all(activeJobs.map((job) =>
      supabase.rpc("neweix_fail_search_embedding_job", {
        p_job_id: job.job_id,
        p_error: message,
      }),
    ));
    throw error;
  }

  if (
    !Array.isArray(vectors) ||
    vectors.length !== activeJobs.length ||
    vectors.some((vector) =>
      !Array.isArray(vector) || vector.length !== 1024 || !vector.every(Number.isFinite),
    )
  ) {
    await Promise.all(activeJobs.map((job) =>
      supabase.rpc("neweix_fail_search_embedding_job", {
        p_job_id: job.job_id,
        p_error: "Workers AI returned an invalid 1024-dimensional embedding response",
      }),
    ));
    throw new Error("Workers AI returned an invalid embedding response.");
  }

  let indexed = 0;
  let failed = 0;
  for (let index = 0; index < activeJobs.length; index += 1) {
    const job = activeJobs[index];
    const vector = vectors[index];
    const { error: updateError } = await supabase
      .from("products")
      .update({
        search_embedding: `[${vector.join(",")}]`,
        search_embedding_model: "@cf/baai/bge-m3",
        search_embedding_updated_at: new Date().toISOString(),
      })
      .eq("id", job.product_id)
      .eq("is_active", true);

    if (updateError) {
      await supabase.rpc("neweix_fail_search_embedding_job", {
        p_job_id: job.job_id,
        p_error: updateError.message,
      });
      failed += 1;
      continue;
    }

    const { error: completeError } = await supabase.rpc(
      "neweix_complete_search_embedding_job",
      { p_job_id: job.job_id },
    );
    if (completeError) {
      console.error("[search-cron] job completion failed", job.job_id, completeError.message);
      failed += 1;
      continue;
    }
    indexed += 1;
  }

  console.log("[search-cron] batch complete", {
    processed: typedJobs.length,
    indexed,
    failed,
    model: "@cf/baai/bge-m3",
  });
}


type CustomerNotificationJob = {
  id: string;
  phone: string;
  message: string;
  attempts: number;
};

function normalizeBulkSmsPhone(phone: string): string | null {
  let digits = phone.replace(/\\D/g, "");
  if (digits.startsWith("00880")) digits = digits.slice(2);
  if (digits.startsWith("01")) digits = `88${digits}`;
  return /^8801[3-9]\\d{8}$/.test(digits) ? digits : null;
}

function getBulkSmsResponseCode(raw: string): number | null {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed === "number" || typeof parsed === "string") {
      const code = Number(parsed);
      return Number.isFinite(code) ? code : null;
    }
    if (parsed && typeof parsed === "object") {
      const record = parsed as Record<string, unknown>;
      const value = record.response_code ?? record.code ?? record.status;
      const code = Number(value);
      return Number.isFinite(code) ? code : null;
    }
  } catch {
    // BulkSMSBD commonly returns a plain numeric code.
  }
  const match = raw.match(/^\\s*(\\d{3,4})\\b/);
  return match ? Number(match[1]) : null;
}

async function processCustomerNotificationQueue(env: Env): Promise<void> {
  if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.SUPABASE_SERVICE_ROLE_KEY) {
    throw new Error("Customer SMS queue is missing Supabase bindings.");
  }
  if (!env.BULKSMSBD_API_KEY || !env.BULKSMSBD_SENDER_ID) {
    throw new Error("Customer SMS queue is missing BulkSMSBD credentials.");
  }

  const supabase = createClient(env.NEXT_PUBLIC_SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data: jobs, error: claimError } = await supabase.rpc(
    "neweix_claim_customer_notifications",
    { p_limit: 10 },
  );
  if (claimError) throw new Error(`Customer SMS queue claim failed: ${claimError.message}`);
  if (!Array.isArray(jobs) || jobs.length === 0) return;

  let sent = 0;
  let failed = 0;
  for (const job of jobs as CustomerNotificationJob[]) {
    const number = normalizeBulkSmsPhone(job.phone);
    if (!number) {
      await supabase.rpc("neweix_fail_customer_notification", {
        p_id: job.id,
        p_error: "Invalid Bangladesh phone number",
      });
      failed += 1;
      continue;
    }

    try {
      const form = new FormData();
      form.set("api_key", env.BULKSMSBD_API_KEY);
      form.set("type", "text");
      form.set("number", number);
      form.set("senderid", env.BULKSMSBD_SENDER_ID);
      form.set("message", job.message.slice(0, 500));

      const response = await fetch("https://bulksmsbd.net/api/smsapi", {
        method: "POST",
        body: form,
        signal: AbortSignal.timeout(12_000),
      });
      const raw = (await response.text()).trim();
      const responseCode = getBulkSmsResponseCode(raw);
      const accepted = response.ok &&
        (responseCode === 202 || (response.status === 202 && responseCode === null));

      if (!accepted) {
        await supabase.rpc("neweix_fail_customer_notification", {
          p_id: job.id,
          p_error: `BulkSMSBD rejected request (HTTP ${response.status}, code ${responseCode ?? "unknown"})`,
        });
        failed += 1;
        continue;
      }

      const { error: completeError } = await supabase.rpc(
        "neweix_complete_customer_notification",
        { p_id: job.id },
      );
      if (completeError) {
        await supabase.rpc("neweix_fail_customer_notification", {
          p_id: job.id,
          p_error: completeError.message,
        });
        failed += 1;
        continue;
      }
      sent += 1;
    } catch (error) {
      await supabase.rpc("neweix_fail_customer_notification", {
        p_id: job.id,
        p_error: error instanceof Error ? error.message : "BulkSMSBD network failure",
      });
      failed += 1;
    }
  }
  console.log("[customer-sms-cron] batch complete", { processed: jobs.length, sent, failed });
}

export default {
  fetch: openNextWorker.fetch,
  async scheduled(
    controller: ScheduledController,
    env: Env,
    _ctx: ExecutionContextLike,
  ): Promise<void> {
    console.log("[neweix-cron] started", controller.cron, new Date(controller.scheduledTime).toISOString());
    const tasks: Promise<void>[] = [processCustomerNotificationQueue(env)];
    if (controller.cron === "*/15 * * * *") {
      tasks.push(processSearchEmbeddingQueue(env));
    }
    const results = await Promise.allSettled(tasks);
    for (const result of results) {
      if (result.status === "rejected") {
        console.error("[neweix-cron] task failed", result.reason instanceof Error ? result.reason.message : "unknown error");
      }
    }
  },
};

